    "Maintainability",
    "Performance",
    "Readability/Understandability",
    "Size",
    "Lack of knowledge",
    "Project constraints",
    "Simplify debugging",
]

CONSTRUCT_FILES = {
    "Lambdas": "/workspace/lambda.csv",
    "Comp.":   "/workspace/comprehension.csv",
    "MRF":     "/workspace/mrf.csv",
    "Proc.":   "/workspace/procedural.csv",
}

def canonical_reason(label: str):
    s = (label or "").strip()
    if not s:
        return None
    low = s.lower()
    if "debug" in low:
        return "Simplify debugging"
    if "project constraint" in low:
        return "Project constraints"
    if "lack of knowledge" in low:
        return "Lack of knowledge"
    if "coding time" in low:
        return "Coding time"
    if "ease of use" in low:
        return "Ease of use"
    if "maintain" in low:
        return "Maintainability"
    if "perform" in low:
        return "Performance"
    if "size" in low:
        return "Size"
    if "readability/understandability" in low or "readability" in low or "understandability" in low:
        return "Readability/Understandability"
    return None

def aggregate_construct(path: str):
    per_participant = defaultdict(set)
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            pid = (row.get("ID") or "").strip()
            if not pid:
                continue
            canon = canonical_reason(row.get("Final Classification") or "")
            if not canon:
                continue
            per_participant[pid].add(canon)
    total = len(per_participant)
    counts = {r: 0 for r in REASONS}
    for pid, rset in per_participant.items():
        for r in rset:
            counts[r] += 1
    return total, counts

for cname, path in CONSTRUCT_FILES.items():
    total, counts = aggregate_construct(path)
    print(f"=== {cname} ===")
    print("participants with at least one coded reason:", total)
    for r in REASONS:
        print(f"  {r:27s}: {counts[r]}")
    print()
